import { GOLDEN } from "./golden";
import { PLAN_JSON_SCHEMA, PROMPT_VERSION } from "./plan";
import { DEFAULT_EFFORT, DEFAULT_MODEL, PRICING } from "./pricing";
import { SYSTEM_PROMPT, USER_TEMPLATE } from "./prompt";
import { DIMENSIONS, METRICS } from "./semantic";

/**
 * The contract between the live TypeScript app and the Python eval harness (ops-ai/ops_ai/contract.json).
 * Generated by `npm run ai:contract`; tests/ops-suite-ai-contract.test.ts fails if the committed file is stale,
 * so the harness always evaluates exactly what production sends.
 */
export function buildContract() {
  return {
    promptVersion: PROMPT_VERSION,
    defaults: { model: DEFAULT_MODEL, effort: DEFAULT_EFFORT },
    request: { max_tokens: 16000, betas: ["server-side-fallback-2026-07-01"], fallbacks: "default" },
    system: SYSTEM_PROMPT,
    userTemplate: USER_TEMPLATE,
    schema: PLAN_JSON_SCHEMA,
    pricing: PRICING,
    semantic: {
      metrics: METRICS.map((m) => ({ key: m.key, fact: m.fact, timed: m.timed })),
      dimensions: DIMENSIONS.map((d) => ({ key: d.key, facts: d.facts, values: d.values?.map((v) => v.value) ?? null })),
    },
    golden: GOLDEN,
  };
}

export const CONTRACT_PATH = "ops-ai/ops_ai/contract.json";
export const contractJson = () => `${JSON.stringify(buildContract(), null, 2)}\n`;
